@app.patch("/audit/{entry_id}", response_model=AuditEntryResponse)
def edit_audit_entry(entry_id: int, body: dict, db: Session = Depends(get_db)):
    from fastapi import HTTPException
    from ledgerlite.models import AuditEntry
    entry = db.get(AuditEntry, entry_id)
    if entry is None:
        raise HTTPException(status_code=404, detail="Audit entry not found")
    for k, v in body.items():
        setattr(entry, k, v)
    db.commit()
    db.refresh(entry)
    return entry
